/**
 * BillingService is Kernel Billing (docs/kernel/billing/vision.md,
 * metering.md): the meter and plan catalog, each org's billing account and
 * plan, its invoices, usage, and budget leases. Usage arrives through each
 * service's spool, never through this API; no request path calls Billing.
 *
 * Namespace of Sylphx Billing on `Sylphx`.
 */
export class BillingApi {
	/** The `meters` collection. */
	readonly meters: MetersCollection
	/** The `plans` collection. */
	readonly plans: PlansCollection
	/** The `billing_accounts` collection. */
	readonly billingAccounts: BillingAccountsCollection
	/** The `invoices` collection. */
	readonly invoices: InvoicesCollection
	/** The `usage_reports` collection. */
	readonly usageReports: UsageReportsCollection
	/** The `budget_leases` collection. */
	readonly budgetLeases: BudgetLeasesCollection

	constructor(client: runtime.Client) {
		this.meters = new MetersCollection(client)
		this.plans = new PlansCollection(client)
		this.billingAccounts = new BillingAccountsCollection(client)
		this.invoices = new InvoicesCollection(client)
		this.usageReports = new UsageReportsCollection(client)
		this.budgetLeases = new BudgetLeasesCollection(client)
	}
}

/** `meters` of Sylphx Billing: Resource type `billing.sylphx.com/Meter`. */
export class MetersCollection {
	private readonly client: runtime.Client

	constructor(client: runtime.Client) {
		this.client = client
	}

	/**
	 * Gets a meter.
	 *
	 * `GET /v1/{name=meters/*}` · permission `billing:read` · effect `read`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `RESOURCE_NOT_FOUND`.
	 */
	async get(request: GetMeterRequest): Promise<Meter> {
		return this.client.call<Meter>({
			method: 'GET',
			path: `/v1/${runtime.pathParam(request.name, 'meters/*', 'name')}`,
			responseType: 'sylphx.billing.v1.Meter',
			mutation: false,
		})
	}

	/**
	 * Lists meters. Anonymous-readable: the pricing page renders from it.
	 *
	 * `GET /v1/meters` · permission `billing:read` · effect `read`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `INVALID_FIELD`, `PAGE_TOKEN_MISMATCH`.
	 */
	async list(request: ListMetersRequest): Promise<ListMetersResponse> {
		return this.client.call<ListMetersResponse>({
			method: 'GET',
			path: `/v1/meters`,
			query: { page_size: request.pageSize, page_token: request.pageToken, filter: request.filter, order_by: request.orderBy },
			responseType: 'sylphx.billing.v1.ListMetersResponse',
			mutation: false,
		})
	}

	/** Every item of every page of `list`. */
	async *listAll(request: ListMetersRequest): AsyncGenerator<Meter> {
		let next: ListMetersRequest = request
		for (;;) {
			const page = await this.list(next)
			yield* page.meters ?? []
			if (page.nextPageToken === undefined || page.nextPageToken === '') return
			next = { ...request, pageToken: page.nextPageToken }
		}
	}
}

