/** `billing_accounts` of Sylphx Billing: Resource type `billing.sylphx.com/BillingAccount`. */
export class BillingAccountsCollection {
	private readonly client: runtime.Client

	constructor(client: runtime.Client) {
		this.client = client
	}

	/**
	 * Gets a billing account.
	 *
	 * `GET /v1/{name=orgs/*\/billing_accounts/*}` · permission `billing:read` · effect `read`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `RESOURCE_NOT_FOUND`.
	 */
	async get(request: GetBillingAccountRequest): Promise<BillingAccount> {
		return this.client.call<BillingAccount>({
			method: 'GET',
			path: `/v1/${runtime.pathParam(request.name, 'orgs/*/billing_accounts/*', 'name')}`,
			responseType: 'sylphx.billing.v1.BillingAccount',
			mutation: false,
		})
	}

	/**
	 * Lists an org's billing accounts: exactly one, `default`.
	 *
	 * `GET /v1/{parent=orgs/*}/billing_accounts` · permission `billing:read` · effect `read`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `INVALID_FIELD`, `PAGE_TOKEN_MISMATCH`.
	 */
	async list(request: ListBillingAccountsRequest): Promise<ListBillingAccountsResponse> {
		return this.client.call<ListBillingAccountsResponse>({
			method: 'GET',
			path: `/v1/${runtime.pathParam(request.parent, 'orgs/*', 'parent')}/billing_accounts`,
			query: { page_size: request.pageSize, page_token: request.pageToken, filter: request.filter, order_by: request.orderBy },
			responseType: 'sylphx.billing.v1.ListBillingAccountsResponse',
			mutation: false,
		})
	}

	/** Every item of every page of `list`. */
	async *listAll(request: ListBillingAccountsRequest): AsyncGenerator<BillingAccount> {
		let next: ListBillingAccountsRequest = request
		for (;;) {
			const page = await this.list(next)
			yield* page.billingAccounts ?? []
			if (page.nextPageToken === undefined || page.nextPageToken === '') return
			next = { ...request, pageToken: page.nextPageToken }
		}
	}

	/**
	 * Updates a billing account: changes plan, spend limit, or billing email.
	 *
	 * `PATCH /v1/{billing_account.name=orgs/*\/billing_accounts/*}` · permission `billing:admin` · effect `write`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `RESOURCE_NOT_FOUND`, `UNKNOWN_FIELD`, `INVALID_FIELD`, `ETAG_MISMATCH`, `IDEMPOTENCY_KEY_REUSED`, `IDEMPOTENCY_IN_PROGRESS`.
	 */
	async update(request: UpdateBillingAccountRequest): Promise<BillingAccount> {
		return this.client.call<BillingAccount>({
			method: 'PATCH',
			path: `/v1/${runtime.pathParam(request.billingAccount?.name, 'orgs/*/billing_accounts/*', 'billing_account.name')}`,
			query: { update_mask: request.updateMask, validate_only: request.validateOnly },
			body: request.billingAccount ?? {},
			bodyType: 'sylphx.billing.v1.BillingAccount',
			responseType: 'sylphx.billing.v1.BillingAccount',
			mutation: true,
		})
	}

	/**
	 * Starts saving a payment method for the org: returns a client secret the
	 * console confirms with Stripe.js, so card data never reaches Sylphx. The
	 * saved method becomes the account's default and is charged off-session
	 * for each finalized invoice.
	 *
	 * `POST /v1/{name=orgs/*\/billing_accounts/*}:setupPaymentMethod` · permission `billing:admin` · effect `write`
	 *
	 * Errors: `UNAUTHENTICATED`, `PERMISSION_DENIED`, `RESOURCE_NOT_FOUND`, `UNAVAILABLE`.
	 */
	async setupPaymentMethod(request: SetupPaymentMethodRequest): Promise<SetupPaymentMethodResponse> {
		return this.client.call<SetupPaymentMethodResponse>({
			method: 'POST',
			path: `/v1/${runtime.pathParam(request.name, 'orgs/*/billing_accounts/*', 'name')}:setupPaymentMethod`,
			body: runtime.omit(request, ['name']),
			bodyType: 'sylphx.billing.v1.SetupPaymentMethodRequest',
			responseType: 'sylphx.billing.v1.SetupPaymentMethodResponse',
			mutation: true,
		})
	}
}

